{
  "findings": [
    {
      "check_id": "CKV_AZURE_114",
      "title": "Key Vault secret missing content_type",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The 'content_type' attribute is not set, which prevents consumers from correctly interpreting the format of the secret value upon retrieval."
    },
    {
      "check_id": "CKV_AZURE_41",
      "title": "Key Vault secret missing expiration_date",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The 'expiration_date' attribute is not set, meaning this secret will never expire automatically, increasing the risk window if credentials are compromised or rotated manually without enforcement."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_secret\" \"database_connection_string\" {\n  name           = \"database-connection-string\"\n  value          = \"Server=tcp:${azurerm_mssql_server.legal_sql_server.fully_qualified_domain_name},1433;Database=${azurerm_mssql_database.legal_metadata_db.name};User ID=${var.sql_admin_username};Password=${var.sql_admin_password};Encrypt=true;TrustServerCertificate=false;Connection Timeout=30;\"\n  key_vault_id   = azurerm_key_vault.legal_keyvault.id\n  depends_on     = [azurerm_mssql_database.legal_metadata_db]\n  content_type   = \"text/plain\"\n  expiration_date = timeadd(timestamp(), \"8760h\")\n}",
  "fix_summary": "Added 'content_type' to specify the secret format and 'expiration_date' using a relative timestamp calculation (1 year) to enforce secret rotation/expiry policies."
}
